+/** Retry a task-producing function up to `n` additional times after rejection. */
+export function retryN<T, E>(n: number, fn: () => Task<T, E>): Task<T, E> {
+  let remaining = Math.max(0, Math.floor(n));
+  const attempt = (): Task<T, E> => {
+    let task: Task<T, E>;
+    try {
+      task = fn();
+    } catch (error) {
+      return Task.reject<T, E>(error as E);
+    }
+    return task.orElse((error) => {
+      if (remaining-- > 0) return attempt();
+      return Task.reject<T, E>(error);
+    });
+  };
+  return attempt();
+}

